-- Test data for DU1. Load with: sqlite3 pijani.db < pijani.sql, or: psql -f pijani.sql
--
-- The script runs in a single transaction. If DROP TABLE fails in PostgreSQL because you created
-- views on these tables, the database stays unchanged. In that case drop those views (DROP VIEW ...)
-- or add CASCADE to the DROP TABLE statements below (this drops the dependent views too) and rerun.

BEGIN;

DROP TABLE IF EXISTS vypil;
DROP TABLE IF EXISTS navstivil;
DROP TABLE IF EXISTS capuje;
DROP TABLE IF EXISTS lubi;

CREATE TABLE lubi (
    Pijan TEXT,
    Alkohol TEXT
);

CREATE TABLE capuje (
    Krcma TEXT,
    Alkohol TEXT,
    Cena DECIMAL
);

CREATE TABLE navstivil (
    Id INTEGER PRIMARY KEY,
    Pijan TEXT,
    Krcma TEXT,
    Od INTEGER
);

CREATE TABLE vypil (
    Id INTEGER,
    Alkohol TEXT,
    Mnozstvo DECIMAL
);





COMMIT;
